/*═══════ Instagram 面板 CSS ═══════ */
.ig-panel,.ig-panel *{margin:0;padding:0;box-sizing:border-box;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;-webkit-tap-highlight-color:transparent;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC","Hiragino Sans GB",sans-serif
}

.ig-panel{
  /* 颜色变量 - 浅色模式 */
  --bg-main:#fff;
  --text-main:#000;
  --text-soft:#737373;
  --bg-secondary:#ECF0F4;
  --bg-tertiary:#DDE3EA;
  --border-light:#d4d4d4;
  --bg-input:rgba(0,0,0,0.04);
  --border-input:rgba(0,0,0,0.08);
  --bg-hover:rgba(0,0,0,0.06);
  --discord-blue:#1a3fc4;

  /* 原来的样式 */
  width:430px;
  margin:8px auto 0;
  background:var(--bg-main);

position:relative;
  left:50%;
  transform:translateX(-50%) scale(var(--ig-scale, 1));
  transform-origin:top center;

  overflow:hidden;
  box-shadow:0 4px 20px rgba(0,0,0,0.10);
  position:relative;
  border-radius:0;
  transition:opacity 0.3s ease,transform 0.38s cubic-bezier(0.32,0.72,0,1),background 0.3s,color 0.3s;

  /* 关键改动：关闭状态完全隐藏 */
  display:none;
}


.ig-panel.open{
  /* 展开时才显示 */
  display:block;
  opacity:1;
  pointer-events:auto;

  /* 加个动画效果 */
  animation:igPanelSlideIn 0.38s cubic-bezier(0.32,0.72,0,1);
}


@keyframes igPanelSlideIn{
  from{
    opacity:0;
    transform:translateX(-50%) translateY(-12px) scale(var(--ig-scale, 1));
  }
  to{
    opacity:1;
    transform:translateX(-50%) translateY(0) scale(var(--ig-scale, 1));
  }
}






