/* ════════ 推荐页 CSS ════════ */

.ig-feed-wrap{--bg:#ffffff;--text:#000000;--text-soft:#737373;--border:#DBDBDB;--btn-bg:#EFF2F5;--charcoal:#2B2B2D;--charcoal-hover:#3A3A3D;--like-red:#FF3040;--ig-blue:#0095F6;--expand-gray:#666E79;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif;-webkit-font-smoothing:antialiased}
.ig-feed-wrap .top-bar{display:flex;align-items:center;justify-content:space-between;padding:14px 16px 12px}
.ig-feed-wrap .top-bar .left,.ig-feed-wrap .top-bar .right{display:flex;align-items:center;color:var(--text)}
.ig-feed-wrap .top-bar .left svg{width:30px;height:30px;stroke-width:1.75}
.ig-feed-wrap .top-bar .center{display:flex;align-items:center;gap:6px;color:var(--text);margin-top:4px}
.ig-feed-wrap .top-bar .center .ig-logo{height:36px;width:auto}
.ig-feed-wrap .top-bar .center .triangle-icon svg{width:14px;height:14px;stroke-width:2.2}
.ig-feed-wrap .top-bar .right .heart-wrap svg{width:32px;height:32px}
.ig-feed-wrap .heart-wrap{position:relative;display:inline-block;line-height:0}
.ig-feed-wrap .heart-wrap .dot{position:absolute;top:3.5px;right:2px;width:8.8px;height:8.8px;background:#ff3040;border-radius:50%;box-shadow:0 0 0 1.7px var(--bg)}
.ig-feed-wrap .stories-bar{display:flex;gap:16px;padding:12px 14px 14px;overflow-x:auto;scrollbar-width:none;border-top:0.5px solid var(--border)}
.ig-feed-wrap .stories-bar::-webkit-scrollbar{display:none}
.ig-feed-wrap .story-item{flex-shrink:0;display:flex;flex-direction:column;align-items:center;gap:6px;width:83px}
.ig-feed-wrap .story-item .username{font-size:10px;font-weight:400;color:var(--text);max-width:83px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ig-feed-wrap .your-story{position:relative;width:83px;height:83px;display:flex;justify-content:center;align-items:center}
.ig-feed-wrap .your-story .avatar-wrapper{width:71px;height:71px;border-radius:50%;overflow:hidden;background:#ddd}
.ig-feed-wrap .your-story .avatar-wrapper img{width:100%;height:100%;object-fit:cover;display:block}
.ig-feed-wrap .add-button{position:absolute;bottom:4px;right:4px;width:22px;height:22px;border-radius:50%;background:#000;box-shadow:0 0 0 2.5px var(--bg);display:flex;justify-content:center;align-items:center;cursor:pointer}
.ig-feed-wrap .add-button svg{width:13px;height:13px;color:#fff}
.ig-feed-wrap .story-ring{width:83px;height:83px;border-radius:50%;padding:2.9px;background:linear-gradient(80deg,#ffe500 0%,#ff7700 30%,#ff0066 62%,#ff00aa 84%,#8800ff 100%);display:flex;justify-content:center;align-items:center;cursor:pointer}
.ig-feed-wrap .story-ring-inner{width:100%;height:100%;border-radius:50%;background:var(--bg);padding:3px;box-sizing:border-box}
.ig-feed-wrap .story-ring-inner img{width:100%;height:100%;border-radius:50%;object-fit:cover;background:#ddd;display:block}
.ig-feed-wrap .post{padding-bottom:8px}
.ig-feed-wrap .post-header{display:flex;align-items:center;padding:10px 14px;gap:10px}
.ig-feed-wrap .post-avatar{width:35px;height:35px;border-radius:50%;overflow:hidden;background:#ddd;flex-shrink:0;cursor:pointer}
.ig-feed-wrap .post-avatar img{width:100%;height:100%;object-fit:cover;display:block}
.ig-feed-wrap .post-userinfo{flex:1;line-height:1.2;min-width:0}
.ig-feed-wrap .post-userinfo .name{font-size:13px;font-weight:580;color:var(--text);cursor:pointer}
.ig-feed-wrap .post-userinfo .subtitle{font-size:10px;font-weight:500;color:var(--text);margin-top:3px}
.ig-feed-wrap .post-follow{font-size:12px;font-weight:600;color:var(--text);background:var(--btn-bg);border:none;border-radius:8px;padding:9px 22px;cursor:pointer}
.ig-feed-wrap .post-more{color:var(--text);display:flex;align-items:center;cursor:pointer}
.ig-feed-wrap .post-more svg{width:22px;height:22px}
.ig-feed-wrap .post-image{width:100%;background:#fafafa;overflow:hidden;cursor:pointer;display:flex;justify-content:center;align-items:center}
.ig-feed-wrap .post-image img{width:100%;height:auto;max-height:600px;object-fit:contain;display:block}
.ig-feed-wrap .post-actions{display:flex;align-items:center;padding:12px 12px 4px}
.ig-feed-wrap .post-actions .left-actions{display:flex;align-items:center;gap:15px;flex:1}
.ig-feed-wrap .action-group{display:flex;align-items:center;gap:5px;cursor:pointer}
.ig-feed-wrap .action-group .count{font-size:13px;font-weight:600;color:var(--text)}
.ig-feed-wrap .action{color:var(--text);display:flex;align-items:center;cursor:pointer}
.ig-feed-wrap .post-actions .action svg{width:26px;height:26px}
.ig-feed-wrap .post-actions .action.like{line-height:0;transition:transform 0.2s ease}
.ig-feed-wrap .post-actions .action.like svg{width:30px;height:30px}
.ig-feed-wrap .post-actions .action.like .heart-outline{display:block}
.ig-feed-wrap .post-actions .action.like .heart-outline path{fill:var(--text);stroke:var(--text);stroke-width:220;stroke-linejoin:round;stroke-linecap:round}
.ig-feed-wrap .post-actions .action.like .heart-filled{fill:var(--like-red);display:none}
.ig-feed-wrap .action.like.liked .heart-outline{display:none}
.ig-feed-wrap .action.like.liked .heart-filled{display:block}
.ig-feed-wrap .action.like.liked{animation:igFeedPop 0.35s ease}
.ig-feed-wrap .post-actions .action.comment svg{transform:scaleX(-1)}

.ig-feed-wrap .post-actions .action.repost svg{transform:scaleX(1)}

.ig-feed-wrap .action.bookmark svg{transition:fill 0.2s ease,stroke 0.2s ease}
.ig-feed-wrap .action.bookmark.saved svg{fill:var(--text);stroke:var(--text)}
.ig-feed-wrap .action.bookmark.saved{animation:igFeedPop 0.35s ease}
@keyframes igFeedPop{0%{transform:scale(1)}40%{transform:scale(1.25)}70%{transform:scale(0.92)}100%{transform:scale(1)}}
.ig-feed-wrap .post-text{padding:8px 14px 6px;font-size:12px;font-weight:460;line-height:1.4;color:var(--text)}
.ig-feed-wrap .post-text .post-username{font-weight:600;margin-right:4px;cursor:pointer}
.ig-feed-wrap .post-text.collapsed{display:flex;align-items:baseline;flex-wrap:nowrap;overflow:hidden}
.ig-feed-wrap .post-text.collapsed .post-username{flex-shrink:0}
.ig-feed-wrap .post-text.collapsed .post-caption{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ig-feed-wrap .post-text.collapsed .more-toggle{flex-shrink:0}
.ig-feed-wrap .post-text.expanded .post-caption{display:inline}
.ig-feed-wrap .post-text.expanded .more-toggle{display:inline}
.ig-feed-wrap .more-toggle{cursor:pointer;font-weight:400;white-space:nowrap}
.ig-feed-wrap .more-toggle .ellipsis{color:var(--text)}
.ig-feed-wrap .more-toggle .more-text{color:var(--expand-gray);font-weight:500}
.ig-feed-wrap .post-meta{padding:6px 14px 20px;font-size:11px;font-weight:500;color:var(--text-soft);display:flex;align-items:center;gap:4px}
.ig-feed-wrap .post-meta .dot-sep{font-weight:900;font-size:13px;color:var(--text-soft);line-height:1;margin-top:-2px}
.ig-feed-wrap .post-meta .translate{color:var(--text);font-weight:600;cursor:pointer}

/* ══════ 帖子轮播 CSS ══════ */
.post-carousel-wrap{position:relative;overflow:hidden;}
.post-image-slider{display:flex;transition:transform 0.32s cubic-bezier(0.4,0,0.2,1);will-change:transform;cursor:grab;}
.post-image-slider:active{cursor:grabbing;}
.post-slide{flex:0 0 100%;width:100%;display:flex;justify-content:center;align-items:center;background:var(--bg,#fafafa);}
.post-slide img{width:100%;height:auto;max-height:600px;object-fit:contain;display:block;pointer-events:none;-webkit-user-drag:none;}
.post-dots-row{display:flex;justify-content:center;align-items:center;padding:12px 0 2px;}
.post-dots{display:flex;align-items:center;gap:4px;}
.post-dot{width:6px;height:6px;border-radius:50%;background:rgba(0,0,0,0.18);transition:background 0.2s,transform 0.2s,width 0.2s;}
.post-dot.active{background:#4F64FF;width:6px;}

/* 上下滚动交给浏览器，左右滑动由轮播处理 */
.post-image-slider {
  touch-action: pan-y pinch-zoom;
}

</style>
</head>
