var byId=function(i){return document.getElementById(i);};

/* ========== 资料数据 ========== */
var DEFAULTS=window.CONFIG;  // 读取顶部配置区，别删

var SK='igPanelData_v1',DARK_KEY='igPanelDark_v1';

function load(){try{return JSON.parse(localStorage.getItem(SK))||{};}catch(e){return{};}}
function save(o){try{localStorage.setItem(SK,JSON.stringify(o));}catch(e){}}
function getVal(k){var o=load();return(o&&o[k]!=null&&o[k]!=='')?o[k]:DEFAULTS[k];}
function setVal(k,v){var o=load();if(v==null||v==='')delete o[k];else o[k]=v;save(o);}

/* ========== 解析气泡 ========== */
function parseBubbles(text){
  if(!text)return'';
  var lines=text.trim().split('\n');
  var html='';
  lines.forEach(function(line){
    line=line.trim();
    if(!line)return;

    // 支持【左】【右】以及旧的【我】【TA】【Ta】【ta】
    if(line.indexOf('【左】')===0||line.indexOf('【TA】')===0||line.indexOf('【Ta】')===0||line.indexOf('【ta】')===0){
      var msg=line.replace(/^【(左|TA|Ta|ta)】/,'').trim();
      html+='<p class="from-them">'+msg+'</p>';
    }
    else if(line.indexOf('【右】')===0||line.indexOf('【我】')===0){
      var msg=line.replace(/^【(右|我)】/,'').trim();
      html+='<p class="from-me">'+msg+'</p>';
    }
  });
  return html;
}

function applyAll(){
  $$('[data-key]').forEach(function(el){  
    var k=el.dataset.key,v=getVal(k);
    if(v==null)return;
    if(el.tagName==='IMG')el.src=v;
    else el.textContent=v;
  });

  var p=$('.ig-panel');if(!p)return;
  $$('.ig-username',p).forEach(function(el){el.textContent=getVal('username');});
  $$('.ig-char-name',p).forEach(function(el){el.textContent=getVal('charName');});


  // 处理对话气泡（从 DOM 读原始文本，避免多行字符串报错）
  var chatArea=$('.dm-chat-area');
  if(chatArea){
    var raw=chatArea.textContent;
    if(raw&&raw.indexOf('【')>-1){
      chatArea.innerHTML=parseBubbles(raw);
    }
  }


  // 处理通知时间
  var bt=byId('bannerTime');
  if(bt&&DEFAULTS.bannerTime)bt.textContent=DEFAULTS.bannerTime;

  // 处理推荐页用户名
  $$('[data-feed-edit-username]').forEach(function(el){
    if(DEFAULTS.post&&DEFAULTS.post.username)el.textContent=DEFAULTS.post.username;
  });
}


