function carDots(){
  var row=$('.post-dots-row'),dc=$('.post-dots');if(!row||!dc)return;
  var n=carSlides().length;dc.innerHTML='';
  if(n<=1){row.style.display='none';return;}
  row.style.display='flex';
  for(var i=0;i<n;i++){var d=document.createElement('div');d.className='post-dot'+(i===carIndex?' active':'');dc.appendChild(d);}
}
function carGo(i){
  var s=carSlides(),sl=$('.post-image-slider');if(!sl||i<0||i>=s.length)return;
  carIndex=i;sl.style.transition='transform 0.32s cubic-bezier(0.4,0,0.2,1)';sl.style.transform='translateX(-'+(carIndex*100)+'%)';
  $$('.post-dot').forEach(function(d,k){d.classList.toggle('active',k===carIndex);});
