  reset:function(src){var sl=$('.post-image-slider');if(!sl)return;sl.innerHTML='';var s=document.createElement('div');s.className='post-slide active';var im=document.createElement('img');im.src=src||'';s.appendChild(im);sl.appendChild(s);carIndex=0;sl.style.transform='translateX(0)';carDots();}
