/* ========== 轮播手势：先判断方向，再锁定 ========== */
var swipe = null;

function resetSwipe(allowSwitch) {
  if (!swipe) return;

  var state = swipe;
  swipe = null;

  var next = carIndex;

  if (allowSwitch && state.axis === 'x') {
    // 用屏幕上的实际距离判断翻页，兼容面板缩放
    var threshold = Math.max(
      30,
      Math.min(50, state.slider.getBoundingClientRect().width * 0.12)
    );

    if (Math.abs(state.dx) >= threshold) {
      next += state.dx < 0 ? 1 : -1;
    }
  }

  next = Math.max(0, Math.min(carSlides().length - 1, next));
  carGo(next);

  if (state.slider.hasPointerCapture(state.id)) {
    state.slider.releasePointerCapture(state.id);
  }
}

document.addEventListener('pointerdown', function(e) {
  var slider = e.target.closest &&
    e.target.closest('.post-image-slider');

  if (!slider || carSlides().length <= 1 || swipe) return;
  if (!e.isPrimary) return;
  if (e.pointerType === 'mouse' && e.button !== 0) return;

  // 将屏幕像素换算成缩放前的 CSS 像素
  var scale = slider.offsetWidth
    ? slider.getBoundingClientRect().width / slider.offsetWidth
    : 1;

  swipe = {
    id: e.pointerId,
    slider: slider,
    startX: e.clientX,
    startY: e.clientY,
    dx: 0,
    axis: null,
    scale: scale || 1
  };
});

document.addEventListener('pointermove', function(e) {
