  var absY = Math.abs(dy);

  if (!swipe.axis) {
    // 小幅抖动不算滑动
    if (Math.max(absX, absY) < 10) return;

    // 明显向下/向上：结束轮播识别，让页面自然滚动
    if (absY > absX * 1.2) {
      resetSwipe(false);
      return;
    }

    // 斜向且方向不明确时继续观察，不急着抢手势
    if (absX <= absY * 1.2) return;

    swipe.axis = 'x';
    swipe.slider.style.transition = 'none';
    swipe.slider.setPointerCapture(e.pointerId);
  }

  if (e.cancelable) e.preventDefault();

  swipe.dx = dx;
  var drag = dx / swipe.scale;

