  var lastIndex = carSlides().length - 1;
  if (
    (carIndex === 0 && dx > 0) ||
    (carIndex === lastIndex && dx < 0)
  ) {
    drag *= 0.25;
  }

  swipe.slider.style.transform =
    'translateX(calc(' + (-carIndex * 100) + '% + ' + drag + 'px))';
